111	<script>
112	(function () {
113	  "use strict";
114	
115	  // ── identidade da conversa ([REDIGIDO]: o estado entre turnos vive no servidor, por
116	  // conversation_id, dentro de um dict em memória do processo — perdido ao reiniciar). O cliente só
117	  // precisa gerar um id estável para esta aba e reenviá-lo em toda chamada de /api/chat/*.
118	  const conversationId = "chat-" + (
119	    window.crypto && crypto.randomUUID ? crypto.randomUUID() : Date.now().toString(16) + Math.random().toString(16).slice(2)
120	  );
121	
122	  const $ = (id) => document.getElementById(id);
123	  const hero = $("hero"), conversa = $("conversa"), fio = $("fio"), doca = $("doca");
124	  const rapidas = $("rapidas"), form = $("form"), entrada = $("entrada"), ajuda = $("ajuda"), paisSel = $("pais");
125	
126	  let dados = {};        // o que o lead já respondeu, nesta aba
127	  let passoAtual = null;  // validador/handler da pergunta em tela
128	  let voltarAoResumo = false; // "alterar" no resumo: responde só o campo escolhido e volta pro resumo
129	  let paises = [{ iso: "BR", nome: "Brasil", ddi: 55, bandeira: "🇧🇷" }]; // fallback até o fetch chegar
130	
131	  function el(tag, cls, html) {
132	    const e = document.createElement(tag);
133	    if (cls) e.className = cls;
134	    if (html != null) e.innerHTML = html;
135	    return e;
136	  }
137	
138	  function rolar() {
139	    setTimeout(() => { const p = fio.closest(".conteudo") || document.scrollingElement; if (p) p.scrollTop = p.scrollHeight; }, 30);
140	  }
141	
142	  function mensagemLead(texto) {
143	    const m = el("div", "msg lead"); const b = el("div", "bolha"); b.textContent = texto;
144	    m.append(b); fio.append(m); rolar();
145	  }
146	
147	  function mensagemBot(html, { quem = "Assistente AutoSeguro", cls = "" } = {}) {
148	    const m = el("div", "msg bot " + cls); const av = el("div", "avatar", "A");
149	    const b = el("div", "bolha", `<span class="quem">${quem}</span>${html}`);
150	    m.append(av, b); fio.append(m); rolar();
151	    return m;
152	  }
153	
154	  function anexar(no) { fio.append(no); rolar(); }
155	
156	  function limparDoca() { rapidas.innerHTML = ""; entrada.oninput = null; }
157	
158	  function mostrarDoca({ placeholder = "", tipo = "text", botoes = [], textoLivre = true, dica = "", pais = false }) {
159	    doca.hidden = false;
160	    limparDoca();
161	    botoes.forEach((b) => {
162	      const x = el("button", "rapida" + (b.primaria ? " primaria" : ""), b.rotulo);
163	      x.type = "button"; x.onclick = () => b.acao();
164	      rapidas.append(x);
165	    });
166	    form.style.display = textoLivre ? "" : "none";
167	    paisSel.hidden = !pais;
168	    entrada.type = tipo; entrada.value = ""; entrada.placeholder = placeholder;
169	    ajuda.textContent = dica; ajuda.className = "ajuda";
170	    if (textoLivre) entrada.focus();
171	    rolar();
172	  }
173	
174	  function esconderDoca() { doca.hidden = true; limparDoca(); }
175	
176	  function erro(msg) { ajuda.textContent = msg; ajuda.className = "ajuda erro"; }
177	
178	  function progresso(n) {
179	    $("passo-txt").textContent = n > 9 ? "Tudo pronto" : `Pergunta ${n} de 9`;
180	    $("barra").style.width = Math.min(n - 1, 9) / 9 * 100 + "%";
181	  }
182	
183	  // ── contato: salvo assim que nome+WhatsApp existem, atualizado quando o e-mail chega — nunca
184	  // espera o fim do fluxo (o corretor pode precisar do contato mesmo se o lead abandonar antes do
185	  // preço). Nome/WhatsApp/e-mail NUNCA entram no payload de /api/chat/cotar (ver cotar(), abaixo).
186	  async function salvarContato() {
187	    if (!dados.nome || !dados.whatsappExibicao) return;
188	    try {
189	      await fetch("/api/chat/contato", {
190	        method: "POST",
191	        headers: { "Content-Type": "application/json" },
192	        body: JSON.stringify({
193	          conversation_id: conversationId,
194	          nome: dados.nome,
195	          whatsapp: dados.whatsappExibicao,
196	          email: dados.email || null,
197	        }),
198	      });
199	    } catch (e) {
200	      // Falha ao salvar contato não pode travar a cotação em andamento — o corretor perde o
201	      // registro deste lead, mas o lead continua a conversa (e o texto de preço, quando existir,
202	      // segue vindo só da /quote via /api/chat/cotar).
203	    }
204	  }
205	
206	  // ── os passos, um por vez, na ordem da issue #46 (B.3) ──────────────────────────
207	  const PASSOS = {
208	    nome() {
209	      progresso(1);
210	      mensagemBot("Para começar, <b>qual é o seu nome completo?</b>");
211	      mostrarDoca({ placeholder: "Nome completo", dica: "Usamos seu nome para o corretor falar com você." });
212	      passoAtual = (v) => {
213	        const nome = v.trim();
214	        const partesValidas = nome.split(/\s+/).filter((p) => (p.match(/[A-Za-zÀ-ÿ]/g) || []).length >= 2);
215	        if (partesValidas.length < 2) return erro("Digite nome e sobrenome.");
216	        mensagemLead(nome); dados.nome = nome; seguir("whatsapp");
217	      };
218	    },
219	    whatsapp() {
220	      progresso(2);
221	      mensagemBot("Qual o seu <b>WhatsApp</b>? Escolha o país e digite o número.");
222	      mostrarDoca({ placeholder: "Número, com DDD", pais: true });
223	      paisSel.innerHTML = "";
224	      paises.forEach((p) => {
225	        const o = document.createElement("option");
226	        o.value = p.iso; o.textContent = `${p.bandeira} ${p.nome} +${p.ddi}`;
227	        if (p.iso === "BR") o.selected = true;
228	        paisSel.append(o);
229	      });
230	      const paisAtual = () => paises.find((p) => p.iso === paisSel.value) || paises[0];
231	      const aplicarMascaraBR = () => {
232	        const d = entrada.value.replace(/\D/g, "").slice(0, 11);
233	        if (d.length > 6) entrada.value = `(${d.slice(0, 2)}) ${d.slice(2, d.length > 10 ? 7 : 6)}-${d.slice(d.length > 10 ? 7 : 6)}`;
234	        else if (d.length > 2) entrada.value = `(${d.slice(0, 2)}) ${d.slice(2)}`;
235	        else entrada.value = d;
236	      };
237	      const aplicarMascaraOutro = () => { entrada.value = entrada.value.replace(/\D/g, "").slice(0, 14); };
238	      const atualizarTextos = () => {
239	        const p = paisAtual();
240	        // Textos EXATOS da issue #46: Brasil "Número, com DDD"; outros "Número de telefone, sem o
241	        // código do país" — nunca redigitados fora deste ponto único.
242	        if (p.iso === "BR") { entrada.placeholder = "Número, com DDD"; ajuda.textContent = "Ex.: (11) [REDIGIDO]8"; }
243	        else { entrada.placeholder = "Número de telefone, sem o código do país"; ajuda.textContent = `Só os números. O código +${p.ddi} já está no país escolhido.`; }
244	      };
245	      paisSel.onchange = () => { entrada.value = ""; entrada.oninput = paisSel.value === "BR" ? aplicarMascaraBR : aplicarMascaraOutro; atualizarTextos(); };
246	      entrada.oninput = aplicarMascaraBR;
247	      atualizarTextos();
248	      passoAtual = (v) => {
249	        const p = paisAtual();
250	        const digitos = v.replace(/\D/g, "");
251	        let exibicao;
252	        if (p.iso === "BR") {
253	          if (digitos.length !== 10 && digitos.length !== 11) return erro("Digite DDD e número, ex.: (11) [REDIGIDO]8.");
254	          const ddd = digitos.slice(0, 2), resto = digitos.slice(2);
255	          exibicao = `+${p.ddi} (${ddd}) ${digitos.length === 11 ? resto.slice(0, 5) + "-" + resto.slice(5) : resto.slice(0, 4) + "-" + resto.slice(4)}`;
256	        } else {
257	          if (digitos.length < 4 || digitos.length > 14) return erro("Digite só os números do telefone, sem o código do país.");
258	          exibicao = `+${p.ddi} ${digitos}`;
259	        }
260	        mensagemLead(exibicao);
261	        dados.whatsappExibicao = exibicao;
262	        salvarContato();
263	        seguir("email");
264	      };
265	    },
266	    email() {
267	      progresso(3);
268	      mensagemBot("Se quiser, deixe seu <b>e-mail</b>. É opcional.");
269	      mostrarDoca({
270	        placeholder: "[REDIGIDO]", tipo: "email",
271	        botoes: [{ rotulo: "Pular", acao: () => { mensagemLead("Prefiro não informar"); dados.email = null; salvarContato(); seguir("idade"); } }],
272	      });
273	      passoAtual = (v) => {
274	        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim())) return erro("Esse e-mail não parece válido. Confira ou toque em Pular.");
275	        mensagemLead(v.trim()); dados.email = v.trim(); salvarContato(); seguir("idade");
276	      };
277	    },
278	    idade() {
279	      progresso(4);
280	      mensagemBot("E <b>quantos anos você tem?</b>");
281	      mostrarDoca({ placeholder: "Sua idade, ex.: 35", tipo: "number", dica: "Usamos a idade para a faixa de preço." });
282	      passoAtual = (v) => {
283	        const n = parseInt(v, 10);
284	        if (!Number.isInteger(n) || n <= 0) return erro("Digite só o número, ex.: 35.");
285	        mensagemLead(`${n} anos`); dados.idade = n;
286	        // Menor de 18: mensagem exata da issue #46, sem tentativa de cotação — decisão de
287	        // política que é só do frontend guiado (nunca chega a chamar /api/chat/cotar).
288	        if (n < 18) return menorDeIdade();
289	        seguir("modelo");
290	      };
291	    },
292	    modelo() {
293	      progresso(5);
294	      mensagemBot("Qual o <b>modelo</b> do seu carro? (ex.: Onix, HB20, Corolla)");
295	      mostrarDoca({ placeholder: "Modelo do carro", dica: "O modelo fica registrado para o corretor; nesta cotação não altera o preço." });
296	      passoAtual = (v) => {
297	        const modelo = v.trim();
298	        if (modelo.length < 2) return erro("Digite o modelo do carro.");
299	        mensagemLead(modelo); dados.veiculo_modelo = modelo; seguir("ano");
300	      };
301	    },
302	    ano() {
